import { Theme } from './settings/types';
import { OrganizacjaIZespRozmowaOnboardingowa } from './components/generated/OrganizacjaIZespRozmowaOnboardingowa';

let theme: Theme = 'light';

function App() {
  function setTheme(theme: Theme) {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }

  setTheme(theme);

  return (
    <>
      <OrganizacjaIZespRozmowaOnboardingowa />
    </>
  ); // %EXPORT_STATEMENT%
}

export default App;

