.onb-address{display:flex;align-items:center;gap:3px;border:1px solid var(--line);border-radius:8px;padding:4px 10px;background:var(--page);font-size:10px;color:var(--muted)}.onb-address input{width:90px;padding:8px 4px;border:0;background:transparent;font-size:12px}.onb-address b{font-weight:500;font-size:11px;color:var(--ink)}
.onb-chips{display:flex;flex-wrap:wrap;gap:8px}.onb-chip{border:1px solid var(--line);background:var(--surface);color:var(--text);font-size:11px!important;line-height:1.5;padding:10px 13px;border-radius:9px;min-height:40px}.onb-chip[aria-pressed=true]{border-color:var(--brand);background:var(--blue-soft);color:var(--brand)}.onb-text{border:0;background:transparent;font-size:11px!important;padding:12px 0;color:var(--brand)}.onb-selected{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}.onb-selected button{border:1px solid var(--brand-light);background:var(--blue-soft);color:var(--brand);border-radius:8px;padding:9px 12px;font-size:10px!important}
.onb-email-list{display:grid;gap:10px}.onb-email-list>div{display:flex;align-items:center;gap:9px}.onb-email-list button{border:0;background:transparent;color:var(--muted);font-size:22px}.onb-email-list span{color:var(--success-text);font-size:10px;white-space:nowrap}.onb-success{border:1px solid var(--line);border-radius:12px;padding:24px;margin-bottom:18px}.onb-success>span{display:grid;place-items:center;border-radius:50%;width:37px;height:37px;background:var(--success-soft);color:var(--success-text)}.onb-success h2{font-size:18px;font-weight:500;line-height:1.6}.onb-success p{font-size:12px;color:var(--muted);line-height:1.8;overflow-wrap:anywhere}
.onb-error{font-size:11px;line-height:1.8;color:var(--negative-text);border-left:2px solid var(--negative);padding:8px 12px;margin:10px 0 20px 45px}.onb-working{font-size:11px;color:var(--muted);margin:12px 0 20px 45px}.onb-chat-foot{border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:10px;padding:18px 25px;font-size:9px;color:var(--muted)}.onb-provenance{max-width:1140px;margin:0 auto;padding:0 0 20px;color:var(--muted);font-size:9px;line-height:1.7}
.onb-inspector{position:fixed;bottom:25px;left:25px;z-index:9999;width:min(360px,calc(100vw - 35px));padding:24px;background:var(--surface);color:var(--ink);border:1px solid var(--brand-light);border-radius:12px;box-shadow:0 10px 50px #0003;font-size:11px}.onb-inspector>button{float:right;background:none;border:0;color:var(--ink);font-size:22px}.onb-inspector h2{font-size:16px}.onb-inspector dl{font-size:10px;line-height:1.7}.onb-inspector dt{color:var(--muted);margin-top:10px}.onb-inspector dd{margin:0;overflow-wrap:anywhere}
.onb-overlay{position:fixed;inset:0;z-index:9998;background:rgba(0,20,40,.5);display:grid;place-items:center;padding:20px}.onb-mail{position:relative;width:min(560px,100%);max-height:90dvh;overflow:auto;padding:42px;background:var(--surface);color:var(--text);border-radius:16px;box-shadow:0 20px 80px #0004}.onb-mail h2{font-size:25px;font-weight:500;line-height:1.4;color:var(--ink);margin:24px 0}.onb-mail>p{font-size:13px;line-height:1.9}.onb-mail .onb-eyebrow{margin-top:38px}.onb-close{position:absolute;top:15px;right:15px;width:32px;height:32px;background:transparent;border:0;color:var(--muted);font-size:24px}
@keyframes onb-appear{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.onb-root *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}@media(max-width:850px){.onb-layout{grid-template-columns:minmax(180px,.65fr) minmax(380px,1.35fr);gap:28px;padding:0 20px 24px}.onb-header{padding:0 20px;height:85px}.onb-story h1{font-size:34px}.onb-story{padding-top:30px}.onb-header-right>span{display:none}.onb-design-tools{align-items:flex-start;flex-direction:column}.onb-provenance{padding:0 20px 15px}.onb-chat{height:calc(100dvh - 210px)}}
@media(max-width:650px){.onb-layout{display:block;padding:0 12px 20px}.onb-story{display:none}.onb-header{height:74px;padding:0 16px}.onb-header svg{max-width:135px}.onb-design-tools{padding:8px 12px;gap:6px}.onb-design-tools>span{font-size:8px}.onb-design-tools>div{gap:5px}.onb-design-tools label{font-size:9px}.onb-design-tools button{font-size:9px;padding:5px}.onb-design-tools select{max-width:140px}.onb-chat{min-height:540px;height:calc(100dvh - 190px);border-radius:15px}.onb-chat-head{padding:17px 16px;gap:11px}.onb-history{padding:20px 14px}.onb-message{gap:9px}.onb-message>p{font-size:12px;padding:13px 14px;max-width:calc(100% - 43px)}.onb-after-bubble{margin-left:43px}.onb-compose input{font-size:12px;padding:8px 10px}.onb-company{padding:16px}.onb-company dl>div{grid-template-columns:74px 1fr;font-size:10px;gap:7px}.onb-company h2{font-size:15px}.onb-address{flex-wrap:wrap}.onb-btn{font-size:10px!important;padding:10px 12px}.onb-chat-foot{padding:15px 16px;font-size:8px}.onb-mail{padding:28px}.onb-mail h2{font-size:22px}.onb-provenance{font-size:8px}.onb-error{margin-left:43px}}

.onb-root [hidden]{display:none!important}

