/* Broken Image Fallback Styles */
img.broken-image-fallback {
  position: relative;
  display: inline-block;
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  object-fit: none;
  object-position: center;
  animation: fadeIn 0.3s ease-in-out;
}

.dark img.broken-image-fallback {
  background: #1f2937;
